//! Radix-2 evaluation domains over the BLS12-381 scalar field, with the
//! conventions of `bellman`: the domain of size `2^k` is generated by
//! `ROOT_OF_UNITY^(2^(32 - k))`, and cosets are shifted by the
//! multiplicative generator 7.

use super::SynthesisError;
use crate::prelude::*;
use crate::sapling::field::Fq;

/// A power-of-two evaluation domain.
pub(crate) struct Domain {
    /// `log2` of the size.
    exp: u32,
    /// The powers `ω^0 .. ω^(n/2 - 1)` of the generator.
    twiddles: Vec<Fq>,
    /// The same for `ω^-1`.
    inv_twiddles: Vec<Fq>,
    /// `n^-1`.
    minv: Fq,
    /// `7^-1`.
    geninv: Fq,
}

/// The powers `base^0 .. base^(n - 1)`.
fn powers(base: Fq, n: usize) -> Vec<Fq> {
    let mut out = Vec::with_capacity(n);
    let mut cur = Fq::ONE;
    for _ in 0..n {
        out.push(cur);
        cur *= base;
    }
    out
}

impl Domain {
    /// The smallest domain holding `len` evaluations.
    pub(crate) fn new(len: usize) -> Result<Self, SynthesisError> {
        let mut m = 1usize;
        let mut exp = 0u32;
        while m < len {
            m *= 2;
            exp += 1;
            if exp >= Fq::S {
                return Err(SynthesisError::PolynomialDegreeTooLarge);
            }
        }
        let mut omega = Fq::ROOT_OF_UNITY;
        for _ in exp..Fq::S {
            omega = omega.square();
        }
        let invert = |v: Fq| v.invert().ok_or(SynthesisError::PolynomialDegreeTooLarge);
        Ok(Domain {
            exp,
            twiddles: powers(omega, m / 2),
            inv_twiddles: powers(invert(omega)?, m / 2),
            minv: invert(Fq::from_u64(m as u64))?,
            geninv: invert(Fq::MULTIPLICATIVE_GENERATOR)?,
        })
    }

    /// The number of points.
    pub(crate) fn size(&self) -> usize {
        1 << self.exp
    }

    /// In-place decimation-in-time transform with the given twiddles.
    fn transform(&self, a: &mut [Fq], twiddles: &[Fq]) {
        let n = a.len();
        debug_assert_eq!(n, self.size());
        let log_n = self.exp;
        for k in 0..n {
            let rk = if log_n == 0 {
                0
            } else {
                k.reverse_bits() >> (usize::BITS - log_n)
            };
            if k < rk {
                a.swap(rk, k);
            }
        }
        let mut m = 1;
        while m < n {
            let step = n / (2 * m);
            for chunk in a.chunks_exact_mut(2 * m) {
                let (lo, hi) = chunk.split_at_mut(m);
                for j in 0..m {
                    let t = hi[j] * twiddles[j * step];
                    hi[j] = lo[j] - t;
                    lo[j] += t;
                }
            }
            m *= 2;
        }
    }

    /// Evaluates the polynomial with coefficients `a` over the domain.
    pub(crate) fn fft(&self, a: &mut [Fq]) {
        self.transform(a, &self.twiddles);
    }

    /// Interpolates the evaluations `a` over the domain.
    pub(crate) fn ifft(&self, a: &mut [Fq]) {
        self.transform(a, &self.inv_twiddles);
        for v in a.iter_mut() {
            *v *= self.minv;
        }
    }

    /// Multiplies the `i`-th coefficient by `g^i`.
    fn distribute_powers(a: &mut [Fq], g: Fq) {
        let mut u = Fq::ONE;
        for v in a.iter_mut() {
            *v *= u;
            u *= g;
        }
    }

    /// Evaluates the polynomial over the coset `7·H`.
    pub(crate) fn coset_fft(&self, a: &mut [Fq]) {
        Self::distribute_powers(a, Fq::MULTIPLICATIVE_GENERATOR);
        self.fft(a);
    }

    /// Interpolates evaluations over the coset `7·H`.
    pub(crate) fn icoset_fft(&self, a: &mut [Fq]) {
        self.ifft(a);
        Self::distribute_powers(a, self.geninv);
    }

    /// The inverse of the vanishing polynomial `X^n - 1` on the coset, where
    /// it is the constant `7^n - 1`.
    pub(crate) fn z_inv_on_coset(&self) -> Result<Fq, SynthesisError> {
        let mut t = Fq::MULTIPLICATIVE_GENERATOR;
        for _ in 0..self.exp {
            t = t.square();
        }
        (t - Fq::ONE)
            .invert()
            .ok_or(SynthesisError::PolynomialDegreeTooLarge)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn eval(coeffs: &[Fq], x: Fq) -> Fq {
        coeffs.iter().rev().fold(Fq::ZERO, |acc, c| acc * x + *c)
    }

    #[test]
    fn transforms_match_evaluation() {
        for len in [1usize, 2, 5, 16, 33] {
            let domain = Domain::new(len).unwrap();
            let n = domain.size();
            assert!(n >= len && n.is_power_of_two());
            let coeffs: Vec<Fq> = (0..n as u64)
                .map(|i| Fq::from_u64(i * i + 3).square() + Fq::from_u64(i))
                .collect();
            let omega = match n {
                1 => Fq::ONE,
                2 => -Fq::ONE,
                _ => domain.twiddles[1],
            };
            if n > 1 {
                assert_eq!(omega.pow_vartime(&[n as u64, 0, 0, 0]), Fq::ONE);
                assert_ne!(omega.pow_vartime(&[n as u64 / 2, 0, 0, 0]), Fq::ONE);
            }

            let mut a = coeffs.clone();
            domain.fft(&mut a);
            let mut x = Fq::ONE;
            for v in &a {
                assert_eq!(*v, eval(&coeffs, x));
                x *= omega;
            }
            domain.ifft(&mut a);
            assert_eq!(a, coeffs);

            domain.coset_fft(&mut a);
            let mut x = Fq::MULTIPLICATIVE_GENERATOR;
            for v in &a {
                assert_eq!(*v, eval(&coeffs, x));
                x *= omega;
            }
            domain.icoset_fft(&mut a);
            assert_eq!(a, coeffs);

            let z = Fq::MULTIPLICATIVE_GENERATOR.pow_vartime(&[n as u64, 0, 0, 0]) - Fq::ONE;
            assert_eq!(domain.z_inv_on_coset().unwrap() * z, Fq::ONE);
        }
    }
}
